frappe.ui.form.on('Supplier', {
    refresh(frm) {
        const map = { 'Compliant': 'green', 'Under Review': 'orange', 'Documents Pending': 'orange',
                      'Suspended': 'red', 'Rejected': 'red', 'Not Onboarded': 'grey' };
        if (frm.doc.custom_compliance_status)
            frm.dashboard.add_indicator(__(frm.doc.custom_compliance_status), map[frm.doc.custom_compliance_status]);
        [['custom_compliance_trade_license_expiry', 'Trade License'],
         ['custom_compliance_vat_cert_expiry', 'VAT Certificate'],
         ['custom_compliance_establishment_expiry', 'Establishment Card']].forEach(([f, lbl]) => {
            if (frm.doc[f] && frappe.datetime.get_diff(frm.doc[f], frappe.datetime.now_date()) < 0)
                frm.dashboard.add_indicator(__('{0} expired', [lbl]), 'red');
        });
        if (['Suspended', 'Rejected', 'Not Onboarded'].includes(frm.doc.custom_compliance_status))
            frm.dashboard.set_headline(
                `<span class="text-danger">${__('Purchase Orders are blocked until this supplier is compliant.')}</span>`);
    }
});
